(function() {
    'use strict';

    class CostDecAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Costo de Decidir';
            this.version = '1.1.0';

            this.PRODUCT_DATA = {
                PA: { name: 'Premium Architectural', volumeShare: 0.12, revenuePerUnit: 48500, varCostTraditional: 28200, varCostABC: 31400, cmTraditional: 20300, cmABC: 17100, machineHoursShare: 0.18 },
                IC: { name: 'Industrial Coatings', volumeShare: 0.63, revenuePerUnit: 12200, varCostTraditional: 7800, varCostABC: 7200, cmTraditional: 4400, cmABC: 5000, machineHoursShare: 0.52 },
                SS: { name: 'Specialty Solvent', volumeShare: 0.25, revenuePerUnit: 89400, varCostTraditional: 41600, varCostABC: 72400, cmTraditional: 47800, cmABC: 17000, machineHoursShare: 0.30 }
            };

            this.CORRECT_VARIANCES = { price: 3.36, efficiency: 6.84, volume: 5.20 };

            this.ROUNDS = [
                {
                    title_en: 'Round 1 — ABC Implementation and Portfolio Re-evaluation',
                    title_es: 'Ronda 1 — ABC y Reevaluacion del Portafolio',
                    briefing_en: '<strong>Welcome to InduColora S.A.S.</strong><br><br>You are the newly appointed General Manager. Revenue is growing (+12% YoY) but net margin has collapsed from 8.2% to 2.1%. Nobody can explain where the profitability went.<br><br>The finance team has prepared an <strong>Activity-Based Costing</strong> analysis. The traditional cost system allocates COP 12.4B in overhead using a single rate based on machine hours (COP 68,889/hr). ABC reveals that activities like production setups, quality testing, and regulatory compliance are driven by very different cost drivers — and the Specialty Solvent (SS) line consumes them disproportionately.<br><br><strong>ABC Revelation:</strong> SS products cost <span class="costdec-sim-negative">340% more</span> per unit than the traditional system estimated. SS has a <span class="costdec-sim-negative">-18% contribution margin</span> under ABC (it appeared at +53.5% under traditional costing). The entire profitability crisis is SS cross-subsidization.<br><br>Review the data panel below and make your strategic decisions.',
                    briefing_es: '<strong>Bienvenido a InduColora S.A.S.</strong><br><br>Eres el nuevo Gerente General. Los ingresos crecen (+12% interanual) pero el margen neto ha caido de 8.2% a 2.1%. Nadie puede explicar a donde fue la rentabilidad.<br><br>El equipo de finanzas ha preparado un analisis de <strong>Costeo Basado en Actividades (ABC)</strong>. El sistema tradicional asigna COP 12.4B en gastos indirectos usando una tasa unica basada en horas maquina (COP 68,889/hr). ABC revela que actividades como configuraciones de produccion, pruebas de calidad y cumplimiento regulatorio tienen generadores de costo muy diferentes — y la linea de Solventes Especiales (SS) los consume desproporcionadamente.<br><br><strong>Revelacion ABC:</strong> Los productos SS cuestan <span class="costdec-sim-negative">340% mas</span> por unidad de lo que estimaba el sistema tradicional. SS tiene un <span class="costdec-sim-negative">margen de contribucion de -18%</span> bajo ABC (aparecia en +53.5% bajo costeo tradicional). Toda la crisis de rentabilidad es subsidio cruzado por SS.<br><br>Revisa el panel de datos y toma tus decisiones estrategicas.',
                    controls: 'round1Controls',
                    dataPanel_en: '<table class="table table-sm"><thead><tr><th>Product</th><th>Revenue/Unit</th><th>CM Traditional</th><th>CM Ratio (Trad.)</th><th>CM ABC</th><th>CM Ratio (ABC)</th></tr></thead><tbody><tr><td><strong>PA</strong> Premium Architectural</td><td>COP 48,500</td><td>COP 20,300</td><td>41.9%</td><td>COP 17,100</td><td>35.3%</td></tr><tr><td><strong>IC</strong> Industrial Coatings</td><td>COP 12,200</td><td>COP 4,400</td><td>36.1%</td><td>COP 5,000</td><td>41.0%</td></tr><tr><td><strong>SS</strong> Specialty Solvent</td><td>COP 89,400</td><td>COP 47,800</td><td class="costdec-sim-positive">53.5%</td><td class="costdec-sim-negative">COP -16,100</td><td class="costdec-sim-negative">-18.0%</td></tr></tbody></table>',
                    dataPanel_es: '<table class="table table-sm"><thead><tr><th>Producto</th><th>Ingreso/Unidad</th><th>MC Tradicional</th><th>Ratio MC (Trad.)</th><th>MC ABC</th><th>Ratio MC (ABC)</th></tr></thead><tbody><tr><td><strong>PA</strong> Arquitectonico Premium</td><td>COP 48,500</td><td>COP 20,300</td><td>41.9%</td><td>COP 17,100</td><td>35.3%</td></tr><tr><td><strong>IC</strong> Recubrimientos Industriales</td><td>COP 12,200</td><td>COP 4,400</td><td>36.1%</td><td>COP 5,000</td><td>41.0%</td></tr><tr><td><strong>SS</strong> Solvente Especial</td><td>COP 89,400</td><td>COP 47,800</td><td class="costdec-sim-positive">53.5%</td><td class="costdec-sim-negative">COP -16,100</td><td class="costdec-sim-negative">-18.0%</td></tr></tbody></table>'
                },
                {
                    title_en: 'Round 2 — Variance Analysis and Make-or-Buy',
                    title_es: 'Ronda 2 — Analisis de Variaciones y Fabricar o Comprar',
                    briefing_en: '<strong>Month 4 Results Are In</strong><br><br>A <strong>COP 15.4M cost overrun</strong> has been reported against the IC production budget. The CFO wants answers. Your task: decompose this variance into its three components.<br><br><strong>Data provided:</strong><br>- TiO2 pigment: paid COP 4,200/kg vs. standard COP 3,800/kg; purchased 8,400 kg<br>- Standard usage: 0.85 kg/unit x 38,000 units = 32,300 kg; actual = 34,100 kg<br>- Budgeted output: 40,000 units; actual: 38,000 units; fixed overhead/unit applied = COP 2,600<br><br>Additionally, a chemical distributor offers to supply SS-grade solvents at COP 67,000/unit (delivered). You must evaluate using relevant cost analysis.<br><br>Finally, set the transfer price for the Inmobiliaria Andina supply agreement for PA coatings.',
                    briefing_es: '<strong>Resultados del Mes 4</strong><br><br>Se ha reportado un <strong>sobrecosto de COP 15.4M</strong> contra el presupuesto de produccion de IC. El CFO quiere respuestas. Tu tarea: descomponer esta variacion en sus tres componentes.<br><br><strong>Datos proporcionados:</strong><br>- Pigmento TiO2: pagado COP 4,200/kg vs. estandar COP 3,800/kg; comprados 8,400 kg<br>- Uso estandar: 0.85 kg/unidad x 38,000 unidades = 32,300 kg; uso real = 34,100 kg<br>- Produccion presupuestada: 40,000 unidades; real: 38,000 unidades; gasto fijo/unidad aplicado = COP 2,600<br><br>Adicionalmente, un distribuidor quimico ofrece suministrar solventes grado SS a COP 67,000/unidad (entregado). Debes evaluar usando analisis de costos relevantes.<br><br>Finalmente, establece el precio de transferencia para el acuerdo con Inmobiliaria Andina para recubrimientos PA.',
                    controls: 'round2Controls',
                    dataPanel_en: '<table class="table table-sm"><thead><tr><th>Variance Component</th><th>Formula</th><th>Responsible Party</th></tr></thead><tbody><tr><td>Materials Price Variance</td><td>(Actual price - Standard price) x Actual qty purchased</td><td>Procurement</td></tr><tr><td>Materials Efficiency Variance</td><td>(Actual qty used - Standard qty allowed) x Standard price</td><td>Production</td></tr><tr><td>Volume Variance</td><td>(Budgeted units - Actual units) x Fixed overhead per unit</td><td>Demand / Sales</td></tr></tbody></table><br><table class="table table-sm"><thead><tr><th>SS Cost Category</th><th>Annual (M COP)</th><th>Avoidable?</th></tr></thead><tbody><tr><td>Direct materials</td><td>1,840</td><td>Yes</td></tr><tr><td>Direct labor</td><td>610</td><td>Yes (partially)</td></tr><tr><td>Variable overhead</td><td>930</td><td>Yes</td></tr><tr><td>Regulatory (40% avoidable)</td><td>280</td><td>Partial — 112</td></tr><tr><td>Factory fixed overhead</td><td>1,220</td><td>No — sunk</td></tr><tr><td>Depreciation</td><td>180</td><td>No — sunk</td></tr></tbody></table>',
                    dataPanel_es: '<table class="table table-sm"><thead><tr><th>Componente</th><th>Formula</th><th>Responsable</th></tr></thead><tbody><tr><td>Variacion de Precio de Materiales</td><td>(Precio real - Precio estandar) x Cant. comprada</td><td>Compras</td></tr><tr><td>Variacion de Eficiencia de Materiales</td><td>(Cant. usada - Cant. estandar permitida) x Precio estandar</td><td>Produccion</td></tr><tr><td>Variacion de Volumen</td><td>(Unidades presup. - Unidades reales) x Gasto fijo por unidad</td><td>Demanda / Ventas</td></tr></tbody></table><br><table class="table table-sm"><thead><tr><th>Categoria de Costo SS</th><th>Anual (M COP)</th><th>Evitable?</th></tr></thead><tbody><tr><td>Materiales directos</td><td>1,840</td><td>Si</td></tr><tr><td>Mano de obra directa</td><td>610</td><td>Si (parcialmente)</td></tr><tr><td>Gastos indirectos variables</td><td>930</td><td>Si</td></tr><tr><td>Regulatorio (40% evitable)</td><td>280</td><td>Parcial — 112</td></tr><tr><td>Gastos fijos de fabrica</td><td>1,220</td><td>No — hundido</td></tr><tr><td>Depreciacion</td><td>180</td><td>No — hundido</td></tr></tbody></table>'
                },
                {
                    title_en: 'Round 3 — Theory of Constraints and Capital Decision',
                    title_es: 'Ronda 3 — Teoria de Restricciones y Decision de Capital',
                    briefing_en: '<strong>Constraint Identified: High-Speed Mixing Lines</strong><br><br>InduColora has 2 high-speed mixing lines running at <strong>100% utilization</strong>. These are the binding constraint on growth. Total mixing line capacity: 4,800 hours/year.<br><br><strong>CM per mixing line hour:</strong><br>- PA: COP 17,100 CM / 2.8 hrs = COP 6,107/hr<br>- IC: COP 5,000 CM / 0.4 hrs = COP 12,500/hr<br>- SS: COP -16,100 CM / 3.2 hrs = COP -5,031/hr (loss)<br><br>IC generates the highest CM per constrained resource. Optimizing the mix means maximizing IC through the constraint first, then PA, then SS last (or not at all).<br><br>A third mixing line is available for lease at COP 380M/year. Additionally, a client requests a custom specialty product: estimated CM of COP 22,000/unit requiring 1.6 mixing hours/unit.',
                    briefing_es: '<strong>Restriccion Identificada: Lineas de Mezclado de Alta Velocidad</strong><br><br>InduColora tiene 2 lineas de mezclado de alta velocidad al <strong>100% de utilizacion</strong>. Son la restriccion limitante para el crecimiento. Capacidad total: 4,800 horas/anio.<br><br><strong>MC por hora de mezclado:</strong><br>- PA: COP 17,100 MC / 2.8 hrs = COP 6,107/hr<br>- IC: COP 5,000 MC / 0.4 hrs = COP 12,500/hr<br>- SS: COP -16,100 MC / 3.2 hrs = COP -5,031/hr (perdida)<br><br>IC genera la mayor MC por recurso restringido. Optimizar la mezcla significa maximizar IC por la restriccion primero, luego PA, y SS al final (o eliminarlo).<br><br>Una tercera linea de mezclado esta disponible por arrendamiento a COP 380M/anio. Adicionalmente, un cliente solicita un producto especial: MC estimada COP 22,000/unidad requiriendo 1.6 horas de mezclado/unidad.',
                    controls: 'round3Controls',
                    dataPanel_en: '<table class="table table-sm"><thead><tr><th>Product</th><th>CM/Unit (ABC)</th><th>Mixing Hours/Unit</th><th>CM per Constraint Hour</th><th>Priority</th></tr></thead><tbody><tr><td>IC</td><td>COP 5,000</td><td>0.4</td><td class="costdec-sim-positive">COP 12,500</td><td>1st</td></tr><tr><td>PA</td><td>COP 17,100</td><td>2.8</td><td>COP 6,107</td><td>2nd</td></tr><tr><td>Custom</td><td>COP 22,000</td><td>1.6</td><td>COP 13,750</td><td>Above IC if accepted</td></tr><tr><td>SS</td><td class="costdec-sim-negative">COP -16,100</td><td>3.2</td><td class="costdec-sim-negative">COP -5,031</td><td>Eliminate</td></tr></tbody></table>',
                    dataPanel_es: '<table class="table table-sm"><thead><tr><th>Producto</th><th>MC/Unidad (ABC)</th><th>Horas Mezclado/Unidad</th><th>MC por Hora Restriccion</th><th>Prioridad</th></tr></thead><tbody><tr><td>IC</td><td>COP 5,000</td><td>0.4</td><td class="costdec-sim-positive">COP 12,500</td><td>1ra</td></tr><tr><td>PA</td><td>COP 17,100</td><td>2.8</td><td>COP 6,107</td><td>2da</td></tr><tr><td>Especial</td><td>COP 22,000</td><td>1.6</td><td>COP 13,750</td><td>Encima de IC si se acepta</td></tr><tr><td>SS</td><td class="costdec-sim-negative">COP -16,100</td><td>3.2</td><td class="costdec-sim-negative">COP -5,031</td><td>Eliminar</td></tr></tbody></table>'
                }
            ];
        }

        initialize(state) {
            if (this._brfTimer) { clearTimeout(this._brfTimer); this._brfTimer = null; }
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    revenue: 28400,
                    netMargin: 2.1,
                    netProfit: 596,
                    totalScore: 0,
                    cumulativeScore: 0,
                    marginHistory: [],
                    scoreHistory: [],
                    revenueHistory: [],
                    profitHistory: [],
                    ssActive: true,
                    r1Event: null,
                    r2Event: null,
                    r3Event: null
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    ssStrategy: 'maintain',
                    paPricing: 'maintain',
                    capacity: 'expandIC',
                    variancePrice: 0,
                    varianceEff: 0,
                    varianceVol: 0,
                    makeBuy: 'make',
                    transferPrice: 'market',
                    tocMix: 'optimize',
                    lease: 'lease',
                    customProduct: 'accept'
                };
            }
            // Undo rollback: the USF framework rewinds currentPeriod and re-calls initialize
            // but does NOT restore domainState. If state is ahead of the current period,
            // restore the entry snapshot for this period so KPIs/score/history roll back
            // correctly (persisted event rolls are kept for deterministic replay).  (v1.1.0)
            var __cp = state.currentPeriod || 1;
            var __ds = state.domainState;
            if (__ds._periodSnaps && __ds._periodSnaps[__cp] &&
                typeof __ds._snapPeriod === 'number' && __ds._snapPeriod > __cp) {
                var __rs = __ds._periodSnaps[__cp];
                Object.keys(__rs).forEach(function(k) { __ds[k] = JSON.parse(JSON.stringify(__rs[k])); });
                __ds._snapPeriod = __cp;
                __ds._periodSnap = JSON.parse(JSON.stringify(__rs));
                Object.keys(__ds._periodSnaps).forEach(function(k) { if (+k > __cp) delete __ds._periodSnaps[k]; });
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var round = (window.mySimulation.state.currentPeriod || 1);

            if (round === 1) {
                var ssEl = document.getElementById('ssStrategyInput');
                if (ssEl) decisions.ssStrategy = ssEl.value;
                var paEl = document.getElementById('paPricingInput');
                if (paEl) decisions.paPricing = paEl.value;
                var capEl = document.getElementById('capacityInput');
                if (capEl) decisions.capacity = capEl.value;
            } else if (round === 2) {
                var vpEl = document.getElementById('variancePriceInput');
                if (vpEl) decisions.variancePrice = parseFloat(vpEl.value) || 0;
                var veEl = document.getElementById('varianceEffInput');
                if (veEl) decisions.varianceEff = parseFloat(veEl.value) || 0;
                var vvEl = document.getElementById('varianceVolInput');
                if (vvEl) decisions.varianceVol = parseFloat(vvEl.value) || 0;
                var mbEl = document.getElementById('makeBuyInput');
                if (mbEl) decisions.makeBuy = mbEl.value;
                var tpEl = document.getElementById('transferPriceInput');
                if (tpEl) decisions.transferPrice = tpEl.value;

                var totalVar = decisions.variancePrice + decisions.varianceEff + decisions.varianceVol;
                if (Math.abs(totalVar - 15.4) > 0.5) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('variance_sum_warning'), 'warning'
                    );
                    return false;
                }
            } else if (round === 3) {
                var tocEl = document.getElementById('tocMixInput');
                if (tocEl) decisions.tocMix = tocEl.value;
                var leaseEl = document.getElementById('leaseInput');
                if (leaseEl) decisions.lease = leaseEl.value;
                var cpEl = document.getElementById('customProductInput');
                if (cpEl) decisions.customProduct = cpEl.value;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            // --- Idempotency guard (v1.1.0) ---
            // This function mutates ds with relative deltas and .push()es history. Resubmitting
            // the SAME period (double-click on submit, or Undo then resubmit) would otherwise
            // compound values, double the score and duplicate history rows. Snapshot the entry
            // state once per period; every re-entry restores it first, then recomputes cleanly.
            var __snapKeys = Object.keys(ds).filter(function(k) { return k.indexOf('_') !== 0; });
            if (ds._snapPeriod === round && ds._periodSnap) {
                var __r = ds._periodSnap;
                __snapKeys.forEach(function(k) { ds[k] = JSON.parse(JSON.stringify(__r[k])); });
            } else {
                var __sv = {};
                __snapKeys.forEach(function(k) { __sv[k] = ds[k]; });
                ds._periodSnap = JSON.parse(JSON.stringify(__sv));
                ds._snapPeriod = round;
                ds._periodSnaps = ds._periodSnaps || {};
                ds._periodSnaps[round] = JSON.parse(JSON.stringify(__sv));
            }
            // Persist each period's random event outcomes so re-entry (undo/resubmit) is
            // deterministic instead of re-rolling the dice. Stored under an underscore key so
            // the idempotency snapshot never clears them.
            ds._rolls = ds._rolls || {};
            var __roll = function(key, prob) {
                if (ds._rolls[key] === undefined) ds._rolls[key] = (Math.random() < prob);
                return ds._rolls[key];
            };

            var score = 0;
            var revenue = ds.revenue;
            var netMargin = ds.netMargin;
            var netProfit = ds.netProfit;
            var eventText = null;

            if (round === 1) {
                var ssCustomerLost = __roll('r1_ss', 0.30);
                if (ssCustomerLost) {
                    ds.r1Event = 'ss_customer_lost';
                    eventText = window.mySimulation.t('event_ss_customer');
                }

                if (d.ssStrategy === 'reprice') {
                    score += 30;
                    var ssRevLoss = ssCustomerLost ? 2800 : 1400;
                    revenue = revenue - ssRevLoss + 2500;
                    netMargin = 4.8;
                } else if (d.ssStrategy === 'drop') {
                    score += 22;
                    var ssRev = 7100;
                    revenue = revenue - ssRev;
                    netMargin = 5.2;
                    ds.ssActive = false;
                } else if (d.ssStrategy === 'outsource') {
                    score += 26;
                    revenue = revenue - 400;
                    netMargin = 4.5;
                } else {
                    score += 5;
                    netMargin = 2.3;
                }

                if (d.paPricing === 'plus10') {
                    score += 20;
                    revenue += 340;
                    netMargin += 0.8;
                } else if (d.paPricing === 'plus18') {
                    score += 14;
                    revenue += 410;
                    netMargin += 0.5;
                } else {
                    score += 8;
                }

                if (d.capacity === 'expandIC') {
                    score += 18;
                    revenue += 1200;
                    netMargin += 0.6;
                } else if (d.capacity === 'newProduct') {
                    score += 12;
                    revenue += 200;
                    netMargin += 0.2;
                } else {
                    score += 3;
                }

                netProfit = Math.round(revenue * netMargin / 100);

            } else if (round === 2) {
                var tio2Spike = __roll('r2_tio2', 0.40);
                if (tio2Spike) {
                    ds.r2Event = 'tio2_spike';
                    eventText = window.mySimulation.t('event_tio2_spike');
                    revenue -= 180;
                    netMargin -= 0.3;
                }

                var regChange = __roll('r2_reg', 0.25);
                if (regChange && ds.ssActive) {
                    ds.r2Event = (ds.r2Event ? ds.r2Event + '+' : '') + 'reg_change';
                    eventText = (eventText ? eventText + '<br>' : '') + window.mySimulation.t('event_reg_change');
                    netMargin -= 0.2;
                }

                var priceErr = Math.abs(d.variancePrice - 3.36);
                var effErr = Math.abs(d.varianceEff - 6.84);
                var volErr = Math.abs(d.varianceVol - 5.20);
                var totalErr = priceErr + effErr + volErr;
                var varianceScore = 0;
                if (totalErr < 0.3) varianceScore = 25;
                else if (totalErr < 1.0) varianceScore = 20;
                else if (totalErr < 2.5) varianceScore = 12;
                else varianceScore = 5;
                score += varianceScore;

                if (d.makeBuy === 'make') {
                    score += 22;
                    netMargin += 0.3;
                } else if (d.makeBuy === 'partial') {
                    score += 14;
                    netMargin += 0.1;
                } else {
                    score += 6;
                    netMargin -= 0.2;
                }

                if (d.transferPrice === 'costPlus') {
                    score += 20;
                    netMargin += 0.4;
                } else if (d.transferPrice === 'negotiated') {
                    score += 14;
                    netMargin += 0.2;
                } else {
                    score += 10;
                    netMargin += 0.1;
                }

                netProfit = Math.round(revenue * netMargin / 100);

            } else if (round === 3) {
                var competitorExit = __roll('r3_comp', 0.20);
                if (competitorExit) {
                    ds.r3Event = 'competitor_exit';
                    eventText = window.mySimulation.t('event_competitor_exit');
                    revenue += 1800;
                    netMargin += 0.5;
                }

                var dividendRequest = __roll('r3_div', 0.35);
                if (dividendRequest) {
                    ds.r3Event = (ds.r3Event ? ds.r3Event + '+' : '') + 'dividend';
                    eventText = (eventText ? eventText + '<br>' : '') + window.mySimulation.t('event_dividend');
                }

                if (d.tocMix === 'optimize') {
                    score += 25;
                    revenue += 2200;
                    netMargin += 1.2;
                } else if (d.tocMix === 'manual') {
                    score += 16;
                    revenue += 1400;
                    netMargin += 0.7;
                } else {
                    score += 6;
                    netMargin += 0.1;
                }

                if (d.lease === 'lease') {
                    score += 18;
                    revenue += 1600;
                    netMargin += 0.4;
                } else {
                    score += 10;
                }

                if (d.customProduct === 'accept') {
                    score += 15;
                    revenue += 680;
                    netMargin += 0.3;
                } else {
                    score += 8;
                }

                netProfit = Math.round(revenue * netMargin / 100);
                if (d.lease === 'lease') netProfit -= 380;   // relevant lease cost (was overwritten pre-1.1.0)
                if (dividendRequest) netProfit -= 800;
            }

            ds.revenue = Math.round(revenue);
            ds.netMargin = Math.round(netMargin * 100) / 100;
            ds.netProfit = netProfit;
            ds.totalScore += score;
            ds.cumulativeScore = ds.totalScore;

            ds.marginHistory.push(ds.netMargin);
            ds.scoreHistory.push(score);
            ds.revenueHistory.push(ds.revenue);
            ds.profitHistory.push(ds.netProfit);

            var self = this;
            var __nextP = state.currentPeriod + 1;
            if (this._brfTimer) clearTimeout(this._brfTimer);
            this._brfTimer = setTimeout(function() {
                self._updateBriefing({ currentPeriod: __nextP });
            }, 500);

            var results = {
                period: round,
                roundScore: score,
                revenue: ds.revenue,
                netMargin: ds.netMargin,
                netProfit: ds.netProfit,
                cumulativeScore: ds.totalScore,
                eventText: eventText
            };

            if (eventText) {
                var alertEl = document.getElementById('eventAlert');
                if (alertEl) {
                    alertEl.innerHTML = eventText;
                    alertEl.style.display = 'block';
                }
            }

            return results;
        }

