        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = 0;
            var lastMargin = 2.1;
            var lastRevenue = 28400;
            for (var i = 0; i < history.length; i++) {
                totalScore += (history[i].results ? history[i].results.roundScore : 0) || 0;
                if (history[i].results) {
                    lastMargin = history[i].results.netMargin || lastMargin;
                    lastRevenue = history[i].results.revenue || lastRevenue;
                }
            }

            var performance = 'Beginner';
            if (totalScore >= 150 && lastMargin >= 6.5) performance = 'Excellent';
            else if (totalScore >= 100 && lastMargin >= 4.5) performance = 'Good';
            else if (totalScore >= 60) performance = 'Developing';

            var insights = [];
            if (lastMargin >= 6.5) insights.push('Strong ABC-driven margin recovery — the profitability crisis is resolved.');
            else if (lastMargin >= 4.0) insights.push('Margin is improving but has not reached the 6.5% target. Review product mix further.');
            else insights.push('The profitability crisis persists. Revisit the SS product strategy and cost allocation.');

            if (totalScore >= 150) insights.push('Outstanding decision quality across all three pillars of managerial accounting.');
            else if (totalScore < 80) insights.push('Decision quality needs improvement. Review variance analysis and relevant cost concepts.');

            return {
                totalScore: totalScore,
                finalMargin: lastMargin,
                finalRevenue: lastRevenue,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
