        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            try {
                if (window.mySimulation && window.mySimulation.language) lang = window.mySimulation.language;
                else if (document.documentElement.lang) lang = document.documentElement.lang.substring(0, 2);
            } catch(e) {}
            if (lang !== 'es') lang = 'en';

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round['briefing_' + lang];

            var dataPanel = document.getElementById('dataPanelContainer');
            var dataPanelContent = document.getElementById('dataPanelContent');
            if (dataPanel && dataPanelContent && round['dataPanel_' + lang]) {
                dataPanelContent.innerHTML = round['dataPanel_' + lang];
                dataPanel.style.display = 'block';
            }

            var alertEl = document.getElementById('eventAlert');
            if (alertEl) alertEl.style.display = 'none';

            for (var r = 0; r < this.ROUNDS.length; r++) {
                var controlId = this.ROUNDS[r].controls;
                var controlEl = document.getElementById(controlId);
                if (controlEl) controlEl.style.display = (r === idx) ? 'block' : 'none';
            }
        }
